/**
 * Chord sets lifted from a library of Ripchord progressions.
 *
 * Each is the first handful of distinct chords from one preset, kept as the
 * actual notes rather than as a name, because the whole point of them is the
 * voicing: where the seventh sits, what is doubled, which note is in the bass.
 * The symbol beside each is worked out from the notes and is only a label for
 * the pad.
 */

export interface PresetChord {
  /** Absolute MIDI notes, as they were written. */
  notes: number[];
  symbol: string;
}

export interface ChordPreset {
  title: string;
  chords: PresetChord[];
}

