/** A preset at random, never the one already loaded if there is a choice. */
export function randomPreset(avoid?: string): ChordPreset {
  const pool = CHORD_PRESETS.filter(p => p.title !== avoid);
  const list = pool.length ? pool : CHORD_PRESETS;
  return list[Math.floor(Math.random() * list.length)];
}
